import { io } from "socket.io-client";
import {store} from '@/store/index.js'
const socket = io(store.state.api, {
  autoConnect: false,
  transports: ["websocket", "polling"], 
  reconnectionAttempts: 3,
  timeout: 5000
});
// 连接管理
export function socket_connect() {
  if (!socket.connected) {
    const username = localStorage.getItem('UresName');
    socket.auth = { username };
    socket.connect();
    
    socket.once('connect', () => {
      console.log('连接成功');
      socket.emit("Urse_login_name", username);
      startHeartbeat();
    });
  }
}
// 断开连接
export function socket_disconnect() {
  if (socket.connected) {
    const username = localStorage.getItem('UresName');
    socket.emit("Urse_logout_name", username);
    socket.disconnect();
    console.log('断开连接');
  }
}
// 心跳机制
function startHeartbeat() {
  const heartbeatInterval = setInterval(() => {
    if (socket.connected) {
      socket.emit('heartbeat');
    } else {
      clearInterval(heartbeatInterval);
    }
  }, 10000);
}

// 状态监听
socket.on('user_offline', (username) => {
  store.state.Online_Numbers=store.state.Online_Numbers.filter((item)=>{
    return item!=username
  })
});

socket.on('force_logout', () => {
  alert('连接超时，请重新登录');
  localStorage.removeItem('UresName');
});
export function socket_user_online_name_list(){
  socket.on('user_online_name_list', (data) => {
    store.state.Online_Numbers=data['name']
    store.state.disconnectNumber=store.state.Urselist.filter((item)=>{
      return !store.state.Online_Numbers.includes(item)
    })
  });
}
export default { socket_connect, socket_disconnect, socket,socket_user_online_name_list};
